class ConfigOperations(object):

    def __init__(self):
        self._admin = admin()
        self._admin_alias = None
        self._bts_type = None
        self._delta_aliases = []

    @staticmethod
    @log_input_and_output
    def adjust_distname(dist_name, bts_id=0, du_id=0, bts_type='GNB'):
        """
        Format given distName so it contains proper mrbts id and nrbts/lnbts id (if needed).
        :param dist_name: object distName with curly brackets in place of mrbts/nrbts/lnbts id,
                          e.g. MRBTS-{}/NRBTS-{}/NRCELL-1
        :param bts_id: Id of BTS, default is 0
        :param du_id: Id of DistributionUnit related to Test Line configuration - gnb.dus[], default is 0
        :param bts_type: GNB or ENB - related to Test Line configuration: gnbs or enbs, defaults to GNB
        :return: formatted distName
        """
        return ConfigOperations._adjust_distname(dist_name, bts_type=bts_type, bts_id=bts_id, du_id=du_id)

    def connect(self, alias, bts_id=0, bts_type='GNB'):
        """
        Connect to BTS
        :param alias:       alias for an admin connection
        :param bts_id:      Id of BTS, default is 0
        :param bts_type:    GNB or ENB - related to Test Line configuration: gnbs or enbs, defaults to GNB
        """
        credentials = get_http_connection_credentials(bts_id=bts_id, bts_type=bts_type)
        if bts_id == 0:
            self._admin.connect_to(bts_host=credentials['ip'], username=credentials['username'],
                                   password=credentials['password'], name=alias)
        else:
            test_pc_credentials = TestLine().get_bts_test_pc_credentials(bts_type=bts_type, bts_id=bts_id)
            try:
                self._admin.setup_admin(remote_host=test_pc_credentials['host'],
                                        remote_host_username=test_pc_credentials['user'],
                                        remote_host_password=test_pc_credentials['password'],
                                        bts_host=credentials['ip'], username=credentials['username'],
                                        password=credentials['password'], name=alias)
            except AliasInUse:
                log_step(f"Alias {alias} is currently in use, connection setup will be skipped.")

        self._admin_alias = alias
        self._bts_type = bts_type.upper()

    def disconnect(self):
        """
        Close connection to BTS
        """
        self._admin.teardown_admin(connection=self._admin_alias)

    @log_input_and_output
    def get_parameter_value(self, dist_name, param_name):
        """
        Get value of parameter from bts configuration.
        :param dist_name: distName of object that contains parameter;
                          with curly brackets in place of mrbts/nrbts/lnbts id, e.g. MRBTS-{}/EQM-1/APEQM-1/RMOD-1
        :param param_name: name of parameter from configuration, in parameter editor is called 'Abbreviation'
        :return: value of given parameter
        """
        return self._get_parameters(dist_name=dist_name, parameters=param_name)[param_name]

    @log_input_and_output
    def get_parameters(self, dist_name):
        """
        Get all parameters of object

        :param dist_name: distName of object with curly brackets in place of mrbts/nrbts/lnbts id,
                          e.g. MRBTS-{}/NRBTS-{}/NRCELL-1
        :return:          all object's parameters and their values in form of dictionary; if object with given dist_name
                          doesn't exist returned dictionary is empty
        :rtype:           dict
        """
        return self._get_parameters(dist_name=dist_name)

    @log_input_and_output
    def get_parameters_by_distname(self, dist_name, parameter_list=None):
        """
        Get values of provided parameters list from BTS.
        :param dist_name: distName of object with curly brackets in place of mrbts/nrbts/lnbts id,
                          e.g. MRBTS-{}/NRBTS-{}/NRCELL-1
        :type dist_name: str
        :param list parameter_list: Optional, list of parameters to be retrieved.
        :type parameter_list: list
        :return: dictionary with parameter names as keys and their values as values
        :rtype: dict
        :raises DistNameDoesNotExist: when object with given dist_name does not exist
        :raises ParameterNotFound: when any of the provided parameters does not exist for given dist_name
        """
        return self._get_parameters(dist_name=dist_name, parameters=parameter_list)

    @log_input_and_output
    def create_parameters_structure_for_tddframestructure(self, current_value, new_parameter_value):
        """
        Create dictionary with new parameter value based on parameter from current TDD frame structure.
        :param current_value: list of dictionary with current values for TDD frame structure, e.g: [{'frameStructureType': 'Static',
                              'Length': '2', 'ulDlDataSlotRatio': '3/7'}]
        :type current_value: list of dict
        :param new_parameter_value: dictionary with parameter name and new value, e.g: {'ulDlDataSlotRatio': '1/4'}
        :type new_parameter_value: dict
        :return: dictionary with new parameter value for TDD frame structure, e.g: {'frameStructureType': 'Static',
                 'Length': '2', 'ulDlDataSlotRatio': '1/4'}
        :rtype: dict
        """
        current_parameter_value = deepcopy(current_value)
        current_value_dict = current_parameter_value[0]

        for parameter, value in current_value_dict.items():
            for new_parameter, new_value in new_parameter_value.items():
                if parameter == new_parameter:
                    current_value_dict[parameter] = new_value

        return current_value_dict

    @log_input_and_output
    def prepare_parameters_dict_for_tddframestructure(self, parameters_dict, cell_technology):
        """
        Prepares dictionary with parameters provided by user. In case of TDD frame structure parameter it will be
        formatted into structured dictionary with "tddFrameStructure" parameter name as key and dictionary of parameter
        name and value as value.
        :param parameters_dict: dictionary with parameters and value provided by user, e.g: {
                                "ulDlDataSlotRatio": "3/7",
                                "pMax": "390",
                                "chBw": "100MHz"},
        :type parameters_dict: dict
        :param cell_technology: cell technology, e.g: 'TDD'
        :type cell_technology: str
        :return: dictionary with a new key added called "tddFrameStructure" for TDD frame structure parameter, e.g:
                 {"tddFrameStructure": {"ulDlDataSlotRatio": "7"},
                  "pMax": "390",
                  "chBw": "100MHz"},
        :rtype: dict
        """
        tdd_structure_dictionary = {}
        list_of_tdd_parameters = ["frameStructureType", "UIDIConfig", "guardPeriodLength", "tdLteUlDlConfig", "ulDlDataSlotRatio"]
        for parameter, value in parameters_dict.items():
            if parameter in list_of_tdd_parameters:
                if cell_technology == "TDD":
                    value = {parameter: value}
                    parameter = "tddFrameStructure"
                else:
                    log_warning(f"Parameter '{parameter}' is not supported for TDD configuration and will be ignored.")
                    continue

            tdd_structure_dictionary[parameter] = value

        return tdd_structure_dictionary

    @log_input_and_output
    def set_parameter_value(self, dist_name, param_name, param_value, skip_parameter_relation_errors=False):
        """
        Set value for parameter from bts configuration.
        :param dist_name: distName of object that contains parameter;
                          with curly brackets in place of mrbts/nrbts/lnbts id, e.g. MRBTS-{}/EQM-1/APEQM-1/RMOD-1
        :param param_name: name of parameter from configuration, in parameter editor is called 'Abbreviation'
        :param param_value: target value for parameter
        :param skip_parameter_relation_errors: change parameter when relation error is present, default is False
        :return: None
        """
        dist_name = self._adjust_distname(dist_name=dist_name, bts_type=self._bts_type)
        self._admin.perform_parameter_recommissioning(dist_name=dist_name, parameter=param_name,
                                                      operation='update', value=param_value, should_activate=True,
                                                      connection=self._admin_alias,
                                                      skip_parameter_relation_errors=skip_parameter_relation_errors)

    @log_input_and_output
    def set_parameters_values(
            self, dist_name, operation="update", activate=True, skip_validation=False, **parameters):
        """
        Updates values of the given parameters on the given dist_name path
        :param dist_name: dist_name path
        :type dist_name: str
        :param operation: Operation that will be performed - create, update, delete. Defaults to "update"
        :type operation: str
        :param activate: determines whether object recommissioning will be performed instantly. Defaults to True
        :type activate: bool
        :param skip_validation: determines whether relation errors should be ignored. Defaults to False
        :type skip_validation: bool
        :param parameters: parameter names and their values to be set. e.g. actETWS=True, actCMAS=False
        :type parameters: dict
        """
        parameters = self._format_parameters(**parameters)

        self._admin.perform_object_recommissioning(
            dist_name=dist_name, parameter=parameters, operation=operation, should_activate=activate,
            connection=self._admin_alias,
            skip_parameter_relation_errors=skip_validation
        )

    @log_input_and_output
    def delete_parameter(self, dist_name, param_name, activate=True, skip_validation=False):
        """
        Deletes the given parameter for the given dist_name path
        :param dist_name: dist_name path, e.g. "MRBTS-40615/NRBTS-40615/NRCELL-0"
        :type dist_name: str
        :param param_name: parameter name to be deleted, e.g. "sfnOffset"
        :type param_name: str
        :param activate: determines whether object recommissioning will be performed instantly. Defaults to True
        :type activate: bool
        :param skip_validation: determines whether relation errors should be ignored. Defaults to False
        :type skip_validation: bool
        """
        dist_name = self._adjust_distname(dist_name=dist_name, bts_type=self._bts_type)

        self._admin.perform_parameter_recommissioning(
            dist_name=dist_name, parameter=param_name,
            operation='delete', value=[], should_activate=activate,
            connection=self._admin_alias,
            skip_parameter_relation_errors=skip_validation)

    @log_input_and_output
    def save_configuration(self, local_dir_path, file_name):
        """
        Saves current SCF file to path provided in local_dir_path under file_name name.
        :param local_dir_path: path to directory to save SCF, i. e. '/tmp'
        :type local_dir_path: str
        :param file_name: name of SCF file, i.e. "SCF.xml"
        :type file_name: str
        """
        self._admin.get_current_scf_file(connection=self._admin_alias, local_dir_path=local_dir_path,
                                         file_name=file_name, timeout=60)

    @log_input_and_output
    def set_parameter_value_in_separate_process(self, dist_name, param_name, param_value,
                                                skip_parameter_relation_errors=False):
        """
        Set value for parameter from bts configuration in separate process.
        :param dist_name: distName of object that contains parameter;
                          with curly brackets in place of mrbts/nrbts/lnbts id, e.g. MRBTS-{}/EQM-1/APEQM-1/RMOD-1
        :param param_name: name of parameter from configuration, in parameter editor is called 'Abbreviation'
        :param param_value: target value for parameter
        :param skip_parameter_relation_errors: change parameter when relation error is present, default is False
        :return: None
        """
        dist_name = self._adjust_distname(dist_name=dist_name, bts_type=self._bts_type)
        self._admin.connect_to(name="perform_parameter_recommissioning")
        self._admin.run_keyword_in_background("perform_parameter_recommissioning",
                                              dist_name=dist_name, parameter=param_name,
                                              operation='update', value=param_value, should_activate=True,
                                              connection="perform_parameter_recommissioning",
                                              skip_parameter_relation_errors=skip_parameter_relation_errors)

    @log_input_and_output
    def perform_commissioning_in_separate_process(self, connection_host, bts_id, scf_file_path):
        """
        Performs commissioning on BTS with file located in scf_file_path in separate proccess.
        :param connection_host: HTTP connection host
        :type connection_host: str
        :param bts_id: ID of BTS, i. e. 2001
        :type bts_id: Unit[int, str]
        :param scf_file_path: path to scf, i. e. /home/ute/scf.xml
        :type scf_file_path: str
        """
        self._admin.connect_to(bts_host=connection_host,
                               name="commissioning")
        self._admin.run_keyword_in_background("perform_commissioning",
                                              bts_id=str(bts_id),
                                              scf_file=scf_file_path,
                                              connection="commissioning")

    @log_input_and_output
    def reset_configuration(self, reset_admin_connection=True):
        """
        Resets BTS configuration.
        :param reset_admin_connection: If True, reset admin connection after configuration reset will be performed,
                                       False otherwise. Default is True.
        :type reset_admin_connection: bool
        """
        reset_bts_configuration(connection=self._admin_alias, reset_admin_connection=reset_admin_connection)

    @log_input_and_output
    def perform_commissioning(self, bts_id, scf_file_path):
        """
        Performs commissioning on BTS with file located in scf_file_path.
        :param bts_id: ID of BTS
        :type bts_id: Unit[int, str]
        :param scf_file_path: path to scf, e.g. /home/ute/scf.xml
        :type scf_file_path: str
        """
        self._admin.perform_commissioning(connection=self._admin_alias, bts_id=str(bts_id), scf_file=scf_file_path)

    def perform_parameters_recommissioning(self, parameters, initial_parameters=None, skip_parameter_relation_errors=False, should_activate=True):
        """
        Performs parameters recommissioning using delta.
        *If initial_parameters arg is provided, their values will be saved in separate delta which can be used to restore configuration
         by 'restore_configuration' method.

        :param parameters: dictionary where key is dist name and value is dictionary of parameter name and its value, e.g.
                           {'MRBTS-50589/NRBTS-50589': {'actNrMixedSOMethod': 'true', 'actNrLBPowerSaving': 'true'},
                            'MRBTS-50589/NRBTS-50589/NRPGRP-1': {'lbpsSOMethod': 'mixed switch off'}}
        :type parameters: dict
        :param initial_parameters: same as parameters arg, but with initial values to be saved in delta which can be used to restore configuration
        :type initial_parameters: dict
        :param skip_parameter_relation_errors: skip parameter relation errors.
        :type skip_parameter_relation_errors: boolean
        :param should_activate: should automatically activate plan.
        :type should_activate: boolean
        """
        return self._perform_parameters_recommissioning(parameters=parameters,
                                                        initial_parameters=initial_parameters,
                                                        skip_parameter_relation_errors=skip_parameter_relation_errors,
                                                        should_activate=should_activate)

    @staticmethod
    @log_input_and_output
    def modify_json_parameter(path_to_json_file, path_to_modified_file, param_name, param_value, json_indent=2):
        """
        Modifies parameter value in json file and saves changed file as new json file.
        :param path_to_json_file: absolute path (including json filename and extension) to file which will be modified,
                                  e.g.: /home/ute/tcs.json
        :type path_to_json_file: str
        :param path_to_modified_file: absolute path (including json filename and extension) to save modified json file,
                                      e.g.: /home/ute/modified_tcs/tcs.json. All directions from provided path must
                                      exist before. In case of the same path as source json file (path_to_json_file),
                                      json file will wil be overwritten.
        :type path_to_modified_file: str
        :param param_name: name of parameter to change
        :type param_name: str
        :param param_value: value of parameter to change
        :type param_value: str or int
        :param json_indent: type of indentation with which elements and object members will be pretty-printed with that
                            indent level, defaults to 2.
                            Possible types of indent:
                            - non-negative integer - number of whitespaces to indent json objects/elements in new lines
                            - string - objects/elements will be start from new line with particular string as indent.
                                       Escape characters are supported also.
                            - None - means that indent is not used, objects/elements will not start form new line.
        :type json_indent: int or str or None
        """
        with open(path_to_json_file) as infile:
            data = json.load(infile)

        data[param_name] = param_value

        with open(path_to_modified_file, 'w') as outfile:
            json.dump(data, outfile, indent=json_indent)

    @log_input_and_output
    def set_float_parameter_value(self, dist_name, param_name, param_value, skip_parameter_relation_errors=False):
        """
        Set value for float parameter from bts configuration.
        The reason for creating separate method for setting float parameter value is the need to
        adjust the value before recommissioning by multiplying it by 10.
        :param dist_name: distName of object that contains parameter;
                          with curly brackets in place of mrbts/nrbts/lnbts id, e.g. MRBTS-{}/EQM-1/APEQM-1/RMOD-1
        :type dist_name: str
        :param param_name: name of parameter from configuration, in parameter editor is called 'Abbreviation'
        :type param_name: str
        :param param_value: target value for parameter
        :type param_value: float
        :param skip_parameter_relation_errors: change parameter when relation error is present, default is False
        :type skip_parameter_relation_errors: bool
        """
        dist_name = self._adjust_distname(dist_name=dist_name, bts_type=self._bts_type)
        self._admin.perform_parameter_recommissioning(dist_name=dist_name, parameter=param_name,
                                                      operation='update', value=float(param_value) * 10,
                                                      should_activate=True,
                                                      connection=self._admin_alias,
                                                      skip_parameter_relation_errors=skip_parameter_relation_errors)

    def get_float_parameter_value(self, dist_name, param_name):
        """
        Get value of float parameter from bts configuration.
        The reason for creating separate method for getting float parameter value is the need to
        adjust the value after getting it by dividing it by 10.
        :param dist_name: distName of object that contains parameter;
                          with curly brackets in place of mrbts/nrbts/lnbts id, e.g. MRBTS-{}/EQM-1/APEQM-1/RMOD-1
        :type dist_name: str
        :param param_name: name of parameter from configuration, in parameter editor is called 'Abbreviation'
        :type param_name: str
        :return: value of given parameter
        :rtype: float
        """
        param_val = self._get_parameters(dist_name=dist_name, parameters=param_name)[param_name]
        return float(param_val) / 10

    @log_input_and_output
    def check_if_parameter_exists(self, dist_name, param_name):
        """
        Checks if parameter exists in BTS configuration.
        :param dist_name: distName of object that contains parameter;
                          with curly brackets in place of mrbts/nrbts/lnbts id, e.g. MRBTS-{}/EQM-1/APEQM-1/RMOD-1
        :type dist_name: str
        :param param_name: name of parameter from configuration, in parameter editor is called 'Abbreviation'
        :type param_name: str
        :return: True if parameter exists, False otherwise
        :rtype: bool
        """
        all_params = self._get_parameters(dist_name=dist_name)
        return param_name in all_params.keys()

    @log_input_and_output
    def create_lbps_period_list(self, start_time, duration):
        """
        Creates time period structure for BTS param 'lbpsPeriodList' from given start time and duration.
        :param start_time: datetime object representing start time of period
        :type start_time: datetime
        :param duration: duration of period in minutes
        :type duration: int | str
        :return: list of dictionaries representing lbpsPeriodList structure
                 e.g [{'lbpsDayOfWeek': 'Mon', 'lbpsDuration': 207, 'lbpsStartTimeHour': 20, 'lbpsStartTimeMinute': 32},
                      {'lbpsDayOfWeek': 'Tue', 'lbpsDuration': 1440, 'lbpsStartTimeHour': 0, 'lbpsStartTimeMinute': 0}]
        :rtype: list[dict]
        """
        return self._create_lbps_period_list(start_time=start_time, duration=duration)

    def activate_deep_sleep_energy_saving_period(self, start_save_period, duration, power_saving_groups, deep_sleep_type='DEEPSLEEP'):
        """
        Activates deep sleep energy saving period on the BTS. To deactivate deep sleep energy saving period use 'restore_configuration' method.

        :param start_save_period: datetime object representing start time of Deep Sleep Energy Saving period
        :type start_save_period: datetime
        :param duration: duration of deep sleep energy saving period in minutes
        :type duration: int | str
        :param power_saving_groups: configuration dist names of power saving groups to configure deep sleep energy saving period on, e.g.
                                    ['MRBTS-50589/NRBTS-50589/NRPGRP-1', 'MRBTS-50589/NRBTS-50589/NRPGRP-2']
        :type power_saving_groups: list[str]
        :param deep_sleep_type: deep sleep energy saving mode (energySavingMode RMOD webM param), either 'DEEPSLEEP' or 'DEEPSLEEP_EXTREME_SFP',
                                defaults to 'DEEPSLEEP'
        :type deep_sleep_type: str
        :raises IncorrectBTSConfiguration: when preconditions for deep sleep energy saving activation are not met
        """
        lbps_period_list_structure = self._create_lbps_period_list(start_time=start_save_period, duration=duration)
        rmods_distn = get_rmods_from_power_saving_groups(connection=self._admin_alias, power_saving_groups=power_saving_groups)
        params_with_values = self._get_deep_sleep_es_period_parameters_distname_value(power_saving_groups=power_saving_groups,
                                                                                      rmod_distnames=rmods_distn,
                                                                                      period_list=lbps_period_list_structure,
                                                                                      deep_sleep_type=deep_sleep_type)
        actual_params_values = {}
        for distname, params in params_with_values.items():
            current_values = get_parameters_by_distn(dist_name=distname, parameters=list(params.keys()), connection=self._admin_alias)
            actual_params_values.update({distname: current_values})

        disabled_deep_sleep = {
            distn: {param: v['disabled'] for param, v in params.items()}
            for distn, params in params_with_values.items()
        }

        try:
            self._validate_parameters(expected=disabled_deep_sleep, actual=actual_params_values)
        except IncorrectBTSConfiguration as e:
            raise IncorrectBTSConfiguration(f"Deep sleep energy saving cannot be activated: Preconditions not met. {e}") from e

        enabled_deep_sleep = {
            distn: {param: v['enabled'] for param, v in params.items()}
            for distn, params in params_with_values.items()
        }

        self._perform_parameters_recommissioning(parameters=enabled_deep_sleep, initial_parameters=actual_params_values)

    def restore_configuration(self):
        """
        Restores configuration parameters saved in all deltas.
        """
        if not self._delta_aliases:
            log_step("No configuration delta file is set. Restore configuration will be skipped.")
            return

        for delta_name in self._delta_aliases:
            if delta_file := self._get_delta(delta_name):
                self._admin.perform_delta_recommissioning(delta_file=delta_file, connection=self._admin_alias)
            self._remove_delta(delta_name=delta_name)

    @staticmethod
    @log_input_and_output
    def _adjust_distname(dist_name, bts_type, bts_id=0, du_id=0):
        mrbts_id = get_bts_instance_id(bts_id=bts_id, du_id=du_id, bts_type=bts_type)
        nrbts_id = get_global_bts_id(bts_id=bts_id, du_id=du_id, bts_type=bts_type)       # lnbts_id for lte
        if 'NRBTS' or 'LNBTS' in dist_name:
            return dist_name.format(mrbts_id, nrbts_id)
        return dist_name.format(mrbts_id)

    @staticmethod
    @log_input_and_output
    def _is_end_of_list(line):
        if '</list>' in line:
            return True

    @staticmethod
    @log_input_and_output
    def _update_list_values(line, list_values):
        re_parameter_and_value = r'\s+<p\s\w+=.(?P<KEY>\w+).>(?P<VALUE>.*)</p>'  # <p name="dlPollByte">25kB</p>
        re_values_in_list = r'\s+<p>(?P<VALUE>.*)</p>'  # <p>10.42.248.70</p>

        if search(re_values_in_list, line):
            list_value = search(re_values_in_list, line)
            list_values.append(list_value.group('VALUE'))
        elif search(re_parameter_and_value, line):
            list_value = search(re_parameter_and_value, line)
            list_values.append((list_value.group('KEY'), list_value.group('VALUE')))
        return False

    @log_input_and_output
    def _get_parameters(self, dist_name, parameters=None):
        dist_name = self._adjust_distname(dist_name=dist_name, bts_type=self._bts_type)
        return get_parameters_by_distn(connection=self._admin_alias, dist_name=dist_name, parameters=parameters)

    @log_input_and_output
    def _format_parameters(self, **parameters):
        formatted_params = [
            {"parameterName": parameter, "operation": "update", "value": value}
            for parameter, value in parameters.items()
        ]

        return formatted_params

    @log_input_and_output
    def _get_deep_sleep_es_period_parameters_distname_value(self, power_saving_groups, rmod_distnames, period_list, deep_sleep_type):
        """
        Gets parameters with dist names required to set Deep Sleep Energy Saving period feature enabled/disabled.

        :param power_saving_groups: configuration dist names of power saving groups to configure deep sleep energy saving period on
        :type power_saving_groups: list[str]
        :param rmod_distnames: rmod configuration dist names related to power saving groups
        :type rmod_distnames: list[str]
        :param period_list: list of dictionaries representing lbpsPeriodList structure,
                            e.g. [{'lbpsDayOfWeek': 'Mon', 'lbpsDuration': 207, 'lbpsStartTimeHour': 20, 'lbpsStartTimeMinute': 32}]
        :type period_list: list[dict]
        :param deep_sleep_type: deep sleep energy saving mode, either 'DEEPSLEEP' or 'DEEPSLEEP_EXTREME_SFP'
        :type deep_sleep_type: str
        :return: parameter dist names as a key and lists of parameters and values, e.g.
                 {'MRBTS-50589/NRBTS-50589': {'actNrMixedSOMethod': {'enabled': 'true', 'disabled': 'false'},
                                              'actNrLBPowerSaving': {'enabled': 'true', 'disabled': 'false'}},
                  'MRBTS-50589/NRBTS-50589/NRPGRP-1': {'lbpsSOMethod': {'enabled': 'mixed switch off', 'disabled': None}}}

        :rtype: dict
        :raises RatTypeError: when unsupported RAT is detected in power saving groups
        """
        power_groups_per_rat_distn = defaultdict(list)
        params_with_distnames = {}

        for psg_distn in power_saving_groups:
            rat_distn = get_bts_rat_distn_from_distn(dist_name=psg_distn)
            power_groups_per_rat_distn[rat_distn].append(psg_distn)

        log_result(f'Power saving groups per RAT dist names:\n{power_groups_per_rat_distn}')

        for rat_distn, power_groups in power_groups_per_rat_distn.items():
            if 'NRBTS' in rat_distn:
                rat = 'nr'
            elif 'LNBTS' in rat_distn:
                rat = 'lte'
            else:
                raise RatTypeError(f"Unsupported RAT: {rat_distn}")

            parameters_values = self._get_deep_sleep_es_period_parameter_values(
                rat=rat, rmod_distnames=rmod_distnames, period_list=period_list, deep_sleep_type=deep_sleep_type
            )
            _params_with_distnames = {
                rat_distn: parameters_values['rat'],
                **{pg_distn: parameters_values['pg'] for pg_distn in power_groups},
                **{rmod_distn: parameters_values['rmod'] for rmod_distn in rmod_distnames}
            }
            params_with_distnames.update(_params_with_distnames)

        return params_with_distnames

    @log_input_and_output
    def _get_deep_sleep_es_period_parameter_values(self, rat, rmod_distnames, period_list, deep_sleep_type):
        """
        Gets parameters with values required to set Deep Sleep Energy Saving period feature enabled/disabled.

        :param rat: 'nr' or 'lte'
        :type rat: str
        :param rmod_distnames: RMOD configuration dist names
        :type rmod_distnames: list[str]
        :param period_list: list of dictionaries representing lbpsPeriodList structure
        :type period_list: list[dict]
        :param deep_sleep_type: deep sleep energy saving mode, either 'DEEPSLEEP' or 'DEEPSLEEP_EXTREME_SFP'
        :type deep_sleep_type: str
        :return: parameters with their values, e.g.
                 {'rat': {'actNrMixedSOMethod': {'enabled': 'true', 'disabled': 'false'},
                            'actNrLBPowerSaving': {'enabled': 'true', 'disabled': 'false'}},
                  'pg': {'lbpsSOMethod': {'enabled': 'mixed switch off', 'disabled': 'any_value'},
                           'lbpsPeriodList': {'enabled': [...], 'disabled': 'any_value'}},
                  'rmod': {'energySavingMode': {'enabled': 'DEEPSLEEP', 'disabled': 'any_value'}}}
        """
        is_nr = rat == 'nr'
        states_true_false = {'enabled': 'true', 'disabled': 'false'}
        states_true_any = {'enabled': 'true', 'disabled': 'any_value'}
        lbps_so_method = 'mixed switch off' if is_nr else 'Mixed Switch Off'

        params = {
            'rat': {},
            'pg': {
                'lbpsSOMethod': {'enabled': lbps_so_method, 'disabled': 'any_value'},
                'lbpsPeriodList': {'enabled': period_list, 'disabled': 'any_value'},
            },
            'rmod': {
                'energySavingMode': {'enabled': deep_sleep_type, 'disabled': 'any_value'}
            }
        }

        if is_nr:
            params['rat'].update({
                'actNrMixedSOMethod': states_true_false,
                'actNrLBPowerSaving': states_true_any
            })
            for _rmod in rmod_distnames:
                is_mmimo = disable_logging(is_rmod_massive_mimo, connection=self._admin_alias, rmod_distn=_rmod)
                key = 'actNrLBmMimoRTXPowerSaving' if is_mmimo else 'actNrLBRTXPowerSaving'
                params['rat'][key] = states_true_any

        else:  # LTE
            params['rat'].update({
                'actMixedSOMethod': states_true_false,
                'actLBPowerSaving': states_true_any,
                'actLBRTXPowerSaving': states_true_any
            })

        return params

    @log_input_and_output
    def _perform_parameters_recommissioning(self, parameters, initial_parameters=None, skip_parameter_relation_errors=False, should_activate=True):
        """
        Performs parameters recommissioning using delta.
        *If initial_parameters arg is provided, their values will be saved in separate delta which can be used to restore configuration
         by 'restore_configuration' method.

        :param parameters: dictionary where key is dist name and value is dictionary of parameter name and its value, e.g.
                           {
                            'MRBTS-50589/NRBTS-50589': {'actNrMixedSOMethod': 'true', 'actNrLBPowerSaving': 'true'},
                            'MRBTS-50589/NRBTS-50589/NRPGRP-1': {'lbpsSOMethod': 'mixed switch off'}
                           }
        :type parameters: dict
        :param initial_parameters: same as parameters arg, but with initial values to be saved in delta which can be used to restore configuration
        :type initial_parameters: dict
        :param skip_parameter_relation_errors: skip parameter relation errors.
        :type skip_parameter_relation_errors: boolean
        :param should_activate: should automatically activate plan.
        :type should_activate: boolean
        """
        delta_name = 'config_operations_parameters_recommissioning'
        try:
            self._add_to_delta(parameters=parameters,
                               delta_name=delta_name)
            self._perform_delta_recommissioning(delta_name=delta_name,
                                                skip_parameter_relation_errors=skip_parameter_relation_errors,
                                                should_activate=should_activate,)
        finally:
            self._remove_delta(delta_name=delta_name)

        if initial_parameters:
            self._add_to_delta(parameters=initial_parameters,
                               delta_name='initial_configuration')

        log_result(f'Successfully performed recommissioning with the following parameters:\n{parameters}')

    @retry_recommissioning
    def _perform_delta_recommissioning(self, delta_name, skip_parameter_relation_errors=False, should_activate=True, timeout=250):
        """
        Performs delta recommissioning using delta with given delta_name.

        :param delta_name: id of delta to be used for recommissioning
        :type delta_name: str
        :param skip_parameter_relation_errors: skip parameter relation errors.
        :type skip_parameter_relation_errors: boolean
        :param should_activate: should automatically activate plan.
        :type should_activate: boolean
        :param timeout: timeout for delta recommissioning operation
        :type timeout: int
        """
        self._admin.perform_delta_recommissioning(delta_file=self._get_delta(delta_name),
                                                  skip_parameter_relation_errors=skip_parameter_relation_errors,
                                                  should_activate=should_activate,
                                                  timeout=timeout,
                                                  connection=self._admin_alias)

    def _create_delta(self, delta_name):
        """
        Creates empty delta.
        """
        self._delta_aliases.append(delta_name)
        self._admin.create_delta(delta_id=delta_name)
        log_result(f"Delta: '{delta_name}' created")

    def _remove_delta(self, delta_name):
        """
        Removes delta with given delta_name.

        :param delta_name: id of delta to be removed
        :type delta_name: str
        """
        self._delta_aliases.remove(delta_name)
        self._admin.remove_delta(delta_id=delta_name)
        log_result(f"Delta: '{delta_name}' removed")

    def _get_delta(self, delta_name):
        """
        Returns delta content with given delta_name.

        :param delta_name: name of delta
        :type delta_name: str
        :return: delta content
        :rtype: str | None
        """
        delta = self._admin.get_delta(delta_id=delta_name)
        if delta == '[]':
            return None
        return delta

    @log_input_and_output
    def _add_to_delta(self, parameters, delta_name):
        """
        Adds given parameters to delta with given delta_name. If delta with given delta_name does not exist, it will be created,
        otherwise parameters will be added to existing delta.

        :param parameters: dictionary where key is dist name and value is dictionary of parameter name and its value, e.g.
                           {'MRBTS-50589/NRBTS-50589': {'actNrMixedSOMethod': 'true', 'actNrLBPowerSaving': 'true'}
        :type parameters: dict
        :param delta_name: delta name
        :type delta_name: str
        """
        if delta_name not in self._delta_aliases:
            self._create_delta(delta_name=delta_name)

        for dist_name, params in parameters.items():
            for param_name, value in params.items():
                self._admin.append_parameter_update_to_delta(dist_name=dist_name, parameter=param_name, value=value, delta_id=delta_name)

        log_result(f"Delta: '{delta_name}' updated")

    @log_input_and_output
    def _validate_parameters(self, expected, actual):
        """
        Validates that actual parameters have expected values. If expected value is 'any_value', actual value will not be validated.

        :param expected: dictionary where key is dist name and value is dictionary of parameter name and its expected value, e.g.
                         {'MRBTS-50589/NRBTS-50589': {'actNrMixedSOMethod': 'true', 'actNrLBPowerSaving': 'true'}}
        :type expected: dict
        :param actual: dictionary where key is dist name and value is dictionary of parameter name and its actual value
        :type actual: dict
        :raises IncorrectBTSConfiguration: when actual parameter value does not match expected value
        """
        errors = []
        for dist_name, params in expected.items():
            actual_params = actual.get(dist_name)
            print(f'actual params for {dist_name}: {actual_params}')
            if not actual_params:
                errors.append(f"Could not find expected dist name: '{dist_name}' in actual parameters.")
                continue
            for param_name, expected_value in params.items():
                actual_value = actual_params.get(param_name)
                if expected_value != 'any_value' and str(expected_value).lower() != str(actual_value).lower():
                    errors.append(f"For dist name '{dist_name}', parameter '{param_name}' has value '{actual_value}', expected '{expected_value}'.")

        if errors:
            raise IncorrectBTSConfiguration("Parameter validation failed with the following errors:\n" + "\n".join(errors))

    def _create_lbps_period_list(self, start_time, duration):
        """
        Creates time period structure for BTS param 'lbpsPeriodList' from given start time and duration.
        :param start_time: datetime object representing start time of period
        :type start_time: datetime
        :param duration: duration of period in minutes
        :type duration: int | str
        :return: list of dictionaries representing lbpsPeriodList structure
                 e.g [{'lbpsDayOfWeek': 'Mon', 'lbpsDuration': 207, 'lbpsStartTimeHour': 20, 'lbpsStartTimeMinute': 32},
                      {'lbpsDayOfWeek': 'Tue', 'lbpsDuration': 1440, 'lbpsStartTimeHour': 0, 'lbpsStartTimeMinute': 0}]
        :rtype: list[dict]
        """
        end_time = start_time + timedelta(minutes=int(duration))
        ps_period_structure = []
        current_start = start_time

        while current_start < end_time:
            if any(period['lbpsDayOfWeek'] == current_start.strftime('%a') for period in ps_period_structure):
                break
            day_end = datetime.combine(current_start.date() + timedelta(days=1), time(0, 0))
            current_end = min(day_end, end_time)
            duration = int((current_end - current_start).total_seconds() / 60)
            ps_period_structure.append({
                'lbpsDayOfWeek': current_start.strftime('%a'),
                'lbpsDuration': duration,
                'lbpsStartTimeHour': current_start.hour,
                'lbpsStartTimeMinute': current_start.minute
            })
            current_start = current_end

        return ps_period_structure
